import {spots,at,finite} from './model.js';
import {escapeHTML as esc,parseCoordinates,normalizeResults,gridUsable,distanceKm} from './search-model.js';
const $=id=>document.getElementById(id),cache=new Map(),forecasts=new Map();let searchRun=0,forecastRun=0,active=null,data=null,chosen=null,busy=false,searchBusy=false,searchController,forecastController;
const fmt=(t,zone)=>new Intl.DateTimeFormat('en-US',{timeZone:zone,weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(t*1000);
const value=(v,unit='',factor=1)=>finite(v)?(v*factor).toFixed(1)+unit:'Unavailable';
async function get(url,signal){const r=await fetch(url,{signal});if(!r.ok)throw Error('Provider unavailable');const d=await r.json();if(d.error)throw Error('Provider unavailable');return d;}
function curated(){forecastRun++;forecastController?.abort();active=null;$('worldPanel').hidden=true;$('curatedLayout').hidden=false;$('searchResults').hidden=true;$('curatedButton').classList.add('chosen');$('worldStatus').textContent='Curated SoCal spots use local profiles and personalized screening.';}
$('curatedButton').onclick=curated;
function selectCurated(i){curated();document.querySelector(`[data-spot="${i}"]`)?.click();$('details').scrollIntoView({behavior:'smooth'});}
function resultButton(label,sub,choose){const b=document.createElement('button');b.type='button';b.className='search-result';const title=document.createElement('strong');title.textContent=label;const detail=document.createElement('span');detail.textContent=sub;b.append(title,detail);b.onclick=choose;return b;}
async function search(e){e?.preventDefault();const q=$('beachQuery').value.trim();if(q.length<2){$('searchStatus').textContent='Enter at least two characters, or latitude, longitude.';return;}const run=++searchRun;searchController?.abort();searchController=new AbortController();const controller=searchController,timer=setTimeout(()=>controller.abort(),15000);searchBusy=true;$('searchSubmit').disabled=true;$('searchResults').hidden=false;$('resultsList').replaceChildren();$('searchStatus').textContent='Searching beaches and coastal places…';
const matches=spots.map((s,i)=>({s,i})).filter(({s})=>(s.name+' '+s.region).toLowerCase().includes(q.toLowerCase()));for(const {s,i} of matches)$('resultsList').append(resultButton(s.name,`CURATED · ${s.region} · Personalized advice`,()=>selectCurated(i)));
try{const coordinates=parseCoordinates(q);let results;if(coordinates){results=[{id:`coordinate-${coordinates.lat}-${coordinates.lon}`,name:'Selected coordinates',region:`${coordinates.lat}, ${coordinates.lon}`,kind:'Coordinates · confirm shoreline',...coordinates}];}else{if(/^-?[\d.]+\s*,\s*-?[\d.]+$/.test(q))throw Error('Coordinates must be latitude −90 to 90, longitude −180 to 180.');const key=q.toLowerCase();if(cache.has(key))results=cache.get(key);else{results=normalizeResults(await get('https://photon.komoot.io/api/?'+new URLSearchParams({q,limit:12,lang:'en'}),searchController.signal));cache.set(key,results);}}
if(run!==searchRun)return;for(const s of results)$('resultsList').append(resultButton(s.name,`${s.kind} · ${s.region} · ${s.lat.toFixed(3)}, ${s.lon.toFixed(3)}`,()=>select(s)));$('searchStatus').textContent=results.length||matches.length?'Choose a result. Only curated spots include local recommendation profiles.':'No matching beaches or places found. Try the beach name plus country, a nearby coastal town, or latitude, longitude.';
}catch(error){if(run!==searchRun)return;$('searchStatus').textContent=error.message.startsWith('Coordinates')?error.message:'Search is unavailable right now. Try again, use coordinates, or choose a curated spot.';}finally{clearTimeout(timer);if(run===searchRun){searchBusy=false;$('searchSubmit').disabled=false;}}}
$('beachSearch').onsubmit=search;$('beachQuery').oninput=()=>{if(searchBusy){searchRun++;searchController?.abort();searchBusy=false;$('searchSubmit').disabled=false;}$('searchResults').hidden=true;};
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('beachQuery').value=b.dataset.example;search();});
async function select(spot,force=false){const run=++forecastRun;forecastController?.abort();forecastController=new AbortController();const controller=forecastController,timer=setTimeout(()=>controller.abort(),20000);active=spot;data=null;chosen=null;busy=true;$('searchResults').hidden=true;$('worldPanel').hidden=false;$('curatedLayout').hidden=true;$('curatedButton').classList.remove('chosen');$('worldPanel').scrollIntoView({behavior:'smooth',block:'start'});render();
try{const stored=forecasts.get(spot.id);if(!force&&stored&&Date.now()-stored.fetched<15*60e3)data=stored;else{const base=new URLSearchParams({latitude:spot.lat,longitude:spot.lon,forecast_days:4,timeformat:'unixtime',timezone:'auto'});const results=await Promise.allSettled([get('https://marine-api.open-meteo.com/v1/marine?'+base+'&cell_selection=sea&hourly=wave_height,swell_wave_height,swell_wave_period,swell_wave_direction',controller.signal),get('https://api.open-meteo.com/v1/forecast?'+base+'&hourly=wind_speed_10m,wind_direction_10m,is_day&wind_speed_unit=kn',controller.signal)]);if(run!==forecastRun)return;const [marine,weather]=results.map(r=>r.status==='fulfilled'?r.value:null);data={marine,weather,fetched:Date.now()};if(marine&&weather)forecasts.set(spot.id,data);}if(run!==forecastRun)return;const now=Date.now()/1000;const hours=(data.marine?.hourly?.time||data.weather?.hourly?.time||[]).filter(t=>t>=Math.floor(now/3600)*3600&&t<=now+48*3600);chosen=hours.find(t=>at(data.weather?.hourly,t,'is_day')===1)??hours[0]??null;data.hours=hours;
}catch{if(run!==forecastRun)return;data={fetched:Date.now(),hours:[]};}finally{clearTimeout(timer);if(run===forecastRun){busy=false;render();}}}
function render(){if(!active)return;const s=active,zone=data?.weather?.timezone||data?.marine?.timezone||'UTC',m=data?.marine,w=data?.weather,usable=gridUsable(s,m),stale=data&&Date.now()-data.fetched>30*60e3;const wave=k=>usable&&!stale?at(m?.hourly,chosen,k):null,wind=k=>!stale?at(w?.hourly,chosen,k):null;
$('worldStatus').textContent='Worldwide forecasts · Local break profile not yet curated';$('worldContent').innerHTML=`<div class="world-heading"><div><span class="pill">FORECAST ONLY · UNCURATED</span><h2>${esc(s.name)}</h2><p>${esc(s.region)} · ${s.lat.toFixed(4)}, ${s.lon.toFixed(4)}</p></div><a class="map-link" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=${s.lat}&mlon=${s.lon}#map=14/${s.lat}/${s.lon}">Confirm location on map ↗</a></div><div class="world-toolbar"><div><label for="worldHour">Forecast hour · ${esc(zone)}</label><select id="worldHour" ${busy||!data?.hours?.length?'disabled':''}>${data?.hours?.length?data.hours.map(t=>`<option value="${t}" ${t===chosen?'selected':''}>${esc(fmt(t,zone))}</option>`).join(''):'<option>'+(busy?'Loading forecast…':'No forecast hours available')+'</option>'}</select></div><button id="worldRefresh" class="refresh" ${busy?'disabled':''}>↻ Refresh forecasts</button></div><p class="world-notice" role="status">${busy?'Fetching live marine and wind forecasts…':!m||!w?'Some forecast data is unavailable. Refresh to retry.':!usable?'No nearby marine grid found. This may be inland or outside useful coastal coverage; marine values are withheld.':stale?'Forecast data is stale. Refresh before using it.':'Live offshore model data. This location has no validated break profile or personalized session rating.'}</p><div class="metrics"><div><small>Offshore total Hs</small><strong>${value(wave('wave_height'),' ft',3.28084)}</strong></div><div><small>Main swell · mean period</small><strong>${value(wave('swell_wave_height'),' ft',3.28084)} / ${value(wave('swell_wave_period'),' s')}</strong></div><div><small>Swell from</small><strong>${value(wave('swell_wave_direction'),'°')}</strong></div><div><small>Wind · direction from</small><strong>${value(wind('wind_speed_10m'),' kn')} / ${value(wind('wind_direction_10m'),'°')}</strong></div></div><div class="reasons world-reasons"><div class="reason"><span class="reason-num">WHAT THE FORECAST TELLS YOU</span><h4>${wind('is_day')===0?'Nighttime at this location':finite(wave('swell_wave_period'))?'Read the swell in context':'Conditions, with context'}</h4><p>${wind('is_day')===0?'This is outside daylight hours. Select a daytime forecast. ':''}Offshore height is not breaking-wave height. ${wave('swell_wave_period')>=14?'Longer-period swell can focus and steepen over the local bottom. ':''}Bottom shape and swell exposure determine what reaches this beach.</p></div><div class="reason"><span class="reason-num">WHAT WE DON’T KNOW YET</span><h4>No board or safety recommendation</h4><p>Bottom type, shoreline orientation, tide window, exits, rips, crowding and water quality are unverified. Local tide predictions are not connected for searched locations. Check with a lifeguard or local surf school.</p></div></div><div class="board"><div class="board-icon">◒</div><div><h4>Want advice matched to your skills and board?</h4><p>Choose a curated spot. Worldwide search adds forecast coverage, not verified local surf knowledge.</p><button class="text-button" id="returnCurated">Explore curated SoCal spots →</button></div></div><p class="data-caption">${data?'Retrieved '+esc(fmt(data.fetched/1000,zone))+'. ':''}${m?`Marine grid ${m.latitude.toFixed(3)}, ${m.longitude.toFixed(3)} · ${distanceKm(s,{lat:m.latitude,lon:m.longitude}).toFixed(1)} km from selected point. `:''}A nearby grid does not prove a location is coastal or surfable. Values beyond 35 km are withheld. Confirm the beach on the map.</p>`;
$('worldHour').onchange=e=>{chosen=Number(e.target.value);render()};$('worldRefresh').onclick=()=>select(active,true);$('returnCurated').onclick=curated;}
setInterval(()=>{if(active&&!busy)select(active);},15*60e3);
document.querySelectorAll('nav a[href="#science"],nav a[href="#recommendations"]').forEach(a=>a.addEventListener('click',curated));
